var n=[{title:`Úsilí a újma`,text:`Svalová únava, těžké dýchání a dočasné pálení mohou k náročnému cvičení patřit. Ostrá bolest, nové nepohodlí kloubu, bolest, která se šíří, nebo závrať nejsou úspěchy. Vaše tělo se přizpůsobuje, když po náročném, ale snesitelném tréninku následuje dost regenerace. Bolest není to, co z toho dělá fungující trénink.`},{title:`Bolest svalů je špatné skóre`,text:`Opožděná bolest svalů je zvlášť častá po neznámém nebo náročném cvičení. Často odeznívá, jak si tělo na pohyb zvyká, zatímco vaše síla a kondice se dál zlepšují. Trénink, po kterém vás svaly sotva bolí, může být stále produktivní, a příliš velká bolest může ztížit pravidelný trénink.`},{title:`Pokrok bez trestání`,text:`Vybírejte opakování, která jsou náročná, ale kontrolovaná, zvyšujte nároky tréninku postupně a zařazujte dny odpočinku nebo lehčí dny. Dokončit sérii s několika opakováními v rezervě může být rozumné. Výzkum neukazuje, že by průměrný zdravý dospělý musel opakovaně dosahovat momentálního svalového selhání, aby získal hodnotné výsledky.`},{title:`Příklad`,text:`Začátečník, který dělá dva tréninky celého těla týdně a stabilně přidává opakování dřepů a kliků, může postupovat, aniž by se po každém tréninku cítil rozbitý.`},{title:`Použití v TrainUp`,text:`Po tréninku ohodnotíte úsilí tréninku (RPE) a nahlásíte případnou bolest s částí těla a cvikem. Pokud něco během tréninku bolí, použijte „Cítím bolest“, aby se cvik okamžitě ukončil; zůstane mimo vaše plány, dokud ho nevrátíte v Profilu. Jakákoli nedávná bolest znamená, že další plán nebude těžší. Nová nebo silná bolest je důvod přestat a nechat ji vyšetřit.`}];var e=[{label:`Stanovisko ACSM z roku 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Praktické doporučení ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`},{label:`NHS: bolest kloubů`,url:`https://www.nhs.uk/symptoms/joint-pain/`}];var a={sections:n,sources:e};export{a as default,n as sections,e as sources};